  | 11, 0 => PREB | 11, 1 => LOOPA | 12, 0 => LOOPB | 12, 1 => LOOPB | _, _ => 0%Z
  end%nat.
Definition exit_shape (i : nat) (cells : list kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 (ReadXBW_blobs1.kr_b_049 ())).
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (CH2.blocks_eqb (nth i G.BLS []) (BLK i) && CHA.foot_chk GT.NF G.HDECL c (BLK i) [] && CBA.regions_eqb (CC.cp_F c) CPF && Nat.eqb (CC.cp_nx c) (NX i) &&
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (CH2.blocks_eqb (nth j G.BLS []) (BLK j) &&
              if Z.eqb pc PC_RS then
                (Z.eqb (SR.ps_pc ps) PC_RS && Nat.eqb i 0 && Nat.eqb j 4
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8288 1 (firstn 1 (BLK 0%nat) ++ skipn 2 (BLK 0%nat)) [] WREGS_RS NEWS_RS None c ps cj (BLK 0%nat) [] (BLK 4%nat) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-224) && Nat.eqb (CH2.ci_nx ci) 44 | None => false end
                 && CL.ps_reg_is ps 10 PE && has cells (KWord (SA RE 512) 8 (EVar 41)) && has cells (KWord (SA RE 520) 8 (EVar 40)))%bool
              else if Z.eqb pc PC_RC then
                (Z.eqb (SR.ps_pc ps) PC_RC && ((Nat.eqb i 1 && Nat.eqb j 6) || (Nat.eqb i 9 && Nat.eqb j 12))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8304 5 (firstn 2 (BLK i)) [] WREGS_RC (NEWS_RC (GRC i)) (Some (EVar (GRC i))) c ps cj (BLK i) [] (BLK j) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-224) && Nat.eqb (CH2.ci_nx ci) (GRC i) | None => false end
                 && CL.ps_reg_is ps 10 RE && CL.ps_reg_is ps 11 EE && has cells (WEQ i 1))%bool
              else if Z.eqb pc PC_PS then
                (Z.eqb (SR.ps_pc ps) PC_PS && ((Nat.eqb i 1 && Nat.eqb j 7) || (Nat.eqb i 6 && Nat.eqb j 10) || (Nat.eqb i 6 && Nat.eqb j 11))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 17600 11 [(chE, ELit 16384)] [] WREGS_PS (NEWS_PS (GPS i)) None c ps cj (BLK i) [] (BLK j) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-224) && Nat.eqb (CH2.ci_nx ci) (GPS i) | None => false end
                 && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 VVE && CL.ps_reg_is ps 12 EE
                 && (if Nat.eqb j 7 then has cells (WEQ 1%nat 0) && has cells (KWord (SA RE 512) 8 (EVar 41)) && has cells (KWord (SA RE 520) 8 (EVar 40))
                     else if Nat.eqb j 10 then has cells (KZ 74) && has cells (KZ 67) && has cells (KWord (SA RE 512) 8 (EVar 41)) && has cells (KWord (SA RE 520) 8 (EVar 40)) && has cells (WEQ 1%nat 1)
                     else has cells (KGE1 74) && has cells (KZ 67) && has cells (KWord (SA RE 520) 8 (EVar 64)) && has cells (KWord (SA RE 512) 8 (ADDE (EVar 64) (EVar 74))) && has cells (WEQ 1%nat 1)))%bool
              else if Z.eqb pc PC_SW then
                (Z.eqb (SR.ps_pc ps) PC_SW && ((Nat.eqb i 2 && Nat.eqb j 8) || (Nat.eqb i 3 && Nat.eqb j 9))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 9952 7 [(chE, ELit 16384)] [] WREGS_SW NEWS_SW None c ps cj (BLK i) [] (BLK j) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-224) && Nat.eqb (CH2.ci_nx ci) 64 | None => false end
                 && CL.ps_reg_is ps 10 PE && has cells (KWord (SA RE 512) 8 (EVar 41)) && has cells (KWord (SA RE 520) 8 (EVar 40))
                 && (if Nat.eqb i 3 then has cells EOFCLR42 else true))%bool
              else if Z.eqb pc PC_SETEC then
                (Z.eqb (SR.ps_pc ps) PC_SETEC &&
                 ((Nat.eqb i 10 && Nat.eqb j 13
                   && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 1024 0 (BLK 10%nat) [] WREGS_SETEC NEWS_SETEC (Some EE) c ps cj (BLK 10%nat) [] (BLK 13%nat) [] with
                        | Some ci => Z.eqb (CH2.ci_csp ci) (-32) && Nat.eqb (CH2.ci_nx ci) 112 | None => false end
                   && CL.ps_reg_is ps 10 EE && CL.ps_reg_is ps 11 (ELit 1) && has cells (KZ 94))
                  || (Nat.eqb i 0 && Nat.eqb j 5 && has cells BADODD42)))%bool
              else false)%bool
          | None => false
          end
      | None =>
          if Z.eqb pc RETPC then (CBA.exit_base_chk GT.NF RETPC c ps && exit_shape i cells)%bool
          else if (Z.eqb pc LOOPA || Z.eqb pc PREB || Z.eqb pc LOOPB)%bool then
            (Z.eqb pc (re_tgt i k) && Z.eqb (SR.ps_pc ps) pc && expr_eqb (CC.cp_meas c) (MEASX i) && link_chk i k cells && RNA.reentry_chk GT.NF c ps (nth (TGT pc) G.CPS G.cp0) (mk_s i pc ps)
             && CHA.goto_amb_chk GT.NF G.HDECL c (BLK i) (BLK (TGT pc)) [] [] (mk_s i pc ps) && re_shape i k cells)%bool
else if Z.eqb pc DEADW then ((Nat.eqb i 6 || Nat.eqb i 12) && has cells (WRAPD i) && has cells (KGE1 (vK i)))%bool   (* [comment removed for export] *)
          else if Z.eqb pc PC_CD then ((Nat.eqb i 3 || Nat.eqb i 9) && CRB.tail_base_chk GT.NF PC_CD c ps && CL.ps_reg_is ps 10 RE && CL.ps_reg_is ps 11 EE
                                       && has cells (KWord (SA RE 512) 8 (EVar (vWE i))) && has cells (KWord (SA RE 520) 8 (EVar (vWB i)))
                                       && (if Nat.eqb i 3 then has cells EOFSET42 else has cells (WEQ 9%nat 0)))%bool
          else false
      end)%bool
  end.
